import React, { createContext, useContext, useEffect, useState } from "react";
import { onAuthStateChanged, signOut } from "firebase/auth";
import { doc, getDoc } from "firebase/firestore";
import { auth, db } from "../firebase";

const ADMIN_UIDS = ["jwxmTNjk75Ra7GhejIeX2C9bTMS2"];

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
  const [currentUser, setCurrentUser] = useState(null);
  const [memberId, setMemberId] = useState(null);
  const [isAdmin, setIsAdmin] = useState(false);
  const [canEditNetworking, setCanEditNetworking] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const unsub = onAuthStateChanged(auth, async (user) => {
      setCurrentUser(user);
      if (user) {
        setIsAdmin(ADMIN_UIDS.includes(user.uid));
        try {
          const snap = await getDoc(doc(db, "users", user.uid));
          if (snap.exists()) {
            const data = snap.data();
            setMemberId(data.memberId ?? null);
            setCanEditNetworking(data.networkingEditor === true);
          } else {
            setMemberId(null);
            setCanEditNetworking(false);
          }
        } catch {
          setMemberId(null);
          setCanEditNetworking(false);
        }
      } else {
        setMemberId(null);
        setIsAdmin(false);
        setCanEditNetworking(false);
      }
      setLoading(false);
    });
    return unsub;
  }, []);

  const logout = () => signOut(auth);

  return (
    <AuthContext.Provider value={{ currentUser, memberId, isAdmin, canEditNetworking, loading, logout }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  return useContext(AuthContext);
}
